# function to compute count_upto with variant flags
def count_upto_variant(X, limit, s, variant="normal"):
    if X < 0:
        return 0
    # if s contains digit > limit -> no powerful
    if any(int(d)>limit for d in s):
        return 0
    xs=str(X)
    m=len(xs)
    n=len(s)
    total=0
    for L in range(n, m):
        p=L-n
        if p==0:
            # check s leading zero? In normal we count 1 if s valid.
            # variants: maybe they exclude s if its first digit ==0? but s starts with non-zero per spec? s is positive integer string, so first not zero.
            total+=1
        else:
            if variant=="limit_pow_p":
                total+= limit * pow(limit+1, p)  # off by one exponent
            elif variant=="limit_plus_one_pow_p":
                total+= pow(limit+1, p)  # count leading zero allowed
            elif variant=="limit_pow_limit_pow":
                total+= pow(limit, p) # another variant
            else:
                total+= limit * pow(limit+1, p-1)
    p=m-n
    if p<0:
        return total
    if p==0:
        if variant=="strict_less":
            if s < xs:
                total+=1
        else:
            if s <= xs:
                total+=1
        return total
    # p>0
    prefix=xs[:p]
    suffix=xs[p:]
    # count less
    count_less=0
    still_tight=True
    for i in range(p):
        bound=int(xs[i])
        low=1 if i==0 else 0
        # variants for low
        if variant=="low_zero_always":
            low=0
        high=bound-1
        # variant: high inclusive limit?
        max_allowed = limit
        # variant: if they treat limit as strictly less?
        if variant=="limit_strict":
            max_allowed = limit-1
        if high > max_allowed:
            high = max_allowed
        if high >= low:
            num = high - low +1
            rem=p-i-1
            if variant=="completions_pow_p":
                completions = pow(limit+1, rem+1)
            elif variant=="completions_pow_limit":
                completions = pow(limit, rem) if rem>0 else 1
            else:
                completions = pow(limit+1, rem)
            count_less+= num*completions
        # stay tight
        # check bound allowed
        if i==0:
            if bound==0:
                still_tight=False
                break
            if bound > limit:
                if variant=="limit_strict":
                    if bound > limit-1:
                        still_tight=False
                        break
                else:
                    still_tight=False
                    break
        else:
            if bound > limit:
                still_tight=False
                break
        # also need to consider variant where they break on bound == limit? no
    total+=count_less
    if still_tight:
        # check suffix
        if variant=="suffix_strict_less":
            if s < suffix:
                total+=1
        elif variant=="suffix_greater":
            if s >= suffix:
                total+=1
        else:
            if s <= suffix:
                total+=1
    return total

def count_range_variant(start,finish,limit,s,variant):
    return count_upto_variant(finish,limit,s,variant)-count_upto_variant(start-1,limit,s,variant)

variants=["normal","strict_less","suffix_strict_less","limit_pow_p","low_zero_always","limit_strict"]
def test_variant():
