# brute helpers for variant enumeration
def make_counter(variant_params):
    # variant_params dict containing choices
    # we'll build counting function closure
    def count_upto(X, limit, s):
        if X <0:
            return 0
        # if s has digit > limit => no numbers
        if any(int(c)>limit for c in s):
            return 0
        xs=str(X)
        m=len(xs)
        n=len(s)
        # short lengths counting
        total=0
        for L in range(n, m):
            p=L-n
            if p==0:
                # count for length == n
                # if variant consider leading zero not allowed, this is 1 if s[0]!='0' else 0
                # s[0] never '0' per spec, so 1
                total+= variant_params.get("short_L_eq_n",1)
            else:
                # p>0
                # formula choices
                formula = variant_params.get("short_formula","normal") # normal: limit*(limit+1)^(p-1)
                if formula=="normal":
                    total+= limit * pow(limit+1, p-1) if limit>0 else 0
                elif formula=="limit_plus1_pow_p":
                    total+= pow(limit+1, p)
                elif formula=="limit_pow_p":
                    total+= pow(limit, p)
                elif formula=="limit_plus1_pow_p_minus_pow":
                    # maybe they count all prefixes 0..limit inclusive for first digit also limit+1
                    # but subtract one for zero?
                    total+= pow(limit+1, p) - pow(limit+1, p-1) # not
                    pass
                elif formula=="limit_pow_p_minus":
                    total+= limit * pow(limit+1, p-1) + (1 if variant_params.get("extra_zero") else 0)
                else:
                    total+= limit * pow(limit+1, p-1)
        p=m-n
        if p<0:
            return total
        if p==0:
            # same length
            # compare s <= xs ?
            cmp_op = variant_params.get("cmp_eq","le") # le or lt
            if cmp_op=="le":
                if s <= xs:
                    total+= variant_params.get("eq_bonus",1)
            else:
                if s < xs:
                    total+=1
            return total
        # p>0
        # count less for same length
        count_less=0
        still_tight=True
        for i in range(p):
            bound=int(xs[i])
            low = variant_params.get("low0", 1 if i==0 else 0) if i==0 else 0
            # Actually low for i>0 always 0
            # but we parametrize
            if i==0:
                low_val = variant_params.get("low_first",1)
            else:
                low_val = 0
            high = bound-1
            # limit cap
            max_allowed = limit
            if variant_params.get("limit_strict"):
                max_allowed = limit-1
            if high > max_allowed:
                high = max_allowed
            if high >= low_val:
                num_choices = high - low_val +1
                rem = p - i -1
                # completions formula
                comp_form = variant_params.get("comp_form","pow_limit+1_rem")
                if comp_form=="pow_limit+1_rem":
                    completions = pow(limit+1, rem)
                elif comp_form=="pow_limit+1_rem_plus1":
                    completions = pow(limit+1, rem+1)
                elif comp_form=="pow_limit_rem":
                    completions = pow(limit, rem) if rem>=0 else 1
                else:
                    completions = pow(limit+1, rem)
                count_less += num_choices * completions
            # check tight digit allowed
            # if bound==0 for first pos -> tight breaks unless low_first==0
            if i==0 and bound==0:
                if low_val==0:
                    # could stay tight with 0
                    if bound > max_allowed:
                        still_tight=False
                        break
                    else:
                        continue
                else:
                    still_tight=False
                    break
            if bound > max_allowed:
                still_tight=False
                break
            # else continue tight
        total+= count_less
        if still_tight:
            # suffix compare
            suffix=xs[p:]
            # s <= suffix ?
            cmp = variant_params.get("suffix_cmp","le")
            if cmp=="le":
                if s <= suffix:
                    total+=1
            elif cmp=="lt":
                if s < suffix:
                    total+=1
            elif cmp=="ge":
                if s >= suffix:
                    total+=1
            else:
                if s <= suffix:
                    total+=1
        return total
    def count_range(start,finish,limit,s):
        # start handling
        offset = variant_params.get("offset", -1) # start-1 or start
        # if offset==-1: use start-1, if 0: use start (exclusive), if 1: ?
        if offset==-1:
            return count_upto(finish,limit,s)-count_upto(start-1,limit,s)
        elif offset==0:
            return count_upto(finish,limit,s)-count_upto(start,limit,s) + (1 if variant_params.get("include_start") else 0)
        else:
            return count_upto(finish,limit,s)-count_upto(start-1,limit,s) + variant_params.get("extra",0)
    return count_range

# enumerate a bunch
import random

# try simple brute force over small param sets
low_first_options=[1,0]
short_formula_options=["normal","limit_plus1_pow_p"]
comp_form_options=["pow_limit+1_rem","pow_limit+1_rem_plus1"]
cmp_eq_options=["le","lt"]
suffix_cmp_options=["le","lt"]
offset_options=[-1,0]
limit_strict_options=[False,True]
short_L_eq_options=[1,0]
eq_bonus_options=[1,0]

best=[]
for low_first in low_first_options:
    for short_formula in short_formula_options:
        for comp_form in comp_form_options:
            for cmp_eq in cmp_eq_options:
                for suffix_cmp in suffix_cmp_options:
                    for offset in offset_options:
                        for limit_strict in limit_strict_options:
                            for short_L_eq in short_L_eq_options:
                                for eq_bonus in [1]:
                                    params=dict(
                                        low_first=low_first,
                                        short_formula=short_formula,
                                        comp_form=comp_form,
                                        cmp_eq=cmp_eq,
                                        suffix_cmp=suffix_cmp,
                                        offset=offset,
                                        limit_strict=limit_strict,
                                        short_L_eq_n=short_L_eq,
