(7244775770970,58490828595615,6,"2060",201768035),
(408142522598107,532089352496953,3,"121220233212332",0),
(900407863935940,961459078569857,9,"581747672523731",0),
]

def brute(s_limit, s_str, X, variant):
    # variant dict
    # We'll implement generic count_upto
    if X < 0:
        return 0
    # s_valid check
    if any(int(c) > s_limit for c in s_str):
        # if variant says ignore s_valid for short lengths? but spec says no powerful numbers
        if variant.get("ignore_s_valid"):
            pass
        else:
            return 0
    xs = str(X)
    m = len(xs)
    n = len(s_str)
    total = 0
    # short lengths
    for L in range(n, m):
        p = L - n
        if p == 0:
            # L == n
            # if s[0]=='0' maybe not count? but s[0]!='0'
            total += variant.get("short_n_bonus",1)  # normally 1
        else:
            # formula
            formula = variant.get("short_formula","normal")
            if formula == "normal":
                total += s_limit * pow(s_limit+1, p-1) if s_limit>=1 else 0
            elif formula == "plus1_pow_p":
                total += pow(s_limit+1, p)
            elif formula == "plus1_pow_p_minus1":
                total += pow(s_limit+1, p) - 1
            elif formula == "limit_pow_p":
                total += pow(s_limit, p)
            elif formula == "limit_plus1_pow_p_minus_limit_pow":
                total += pow(s_limit+1, p) - pow(s_limit, p)
            elif formula == "normal_plus1":
                total += s_limit * pow(s_limit+1, p-1) + 1
            elif formula == "zero":
                total += 0
            else:
                total += s_limit * pow(s_limit+1, p-1)

    p = m - n
    if p < 0:
        return total
    if p == 0:
        # same length as s
        op = variant.get("eq_op","le") # le, lt, ge, gt
        if op == "le":
            if s_str <= xs:
                total += variant.get("eq_bonus",1)
        elif op == "lt":
            if s_str < xs:
                total += 1
        elif op == "ge":
            if s_str >= xs:
                total += 1
        elif op == "gt":
            if s_str > xs:
                total += 1
        elif op == "always":
            total += 1
        return total
    # p >0
    # count prefixes < prefix_X that are valid
    # we have two methods: iterative count_less or convert prefix to base
    method = variant.get("prefix_method","iterative")
    if method == "iterative":
        count_less = 0
        still_tight = True
        for i in range(p):
            bound = int(xs[i])
            low = variant.get("low_first",1) if i==0 else 0
            # high bound for choices
            high = bound -1
            max_allowed = s_limit
            if variant.get("limit_strict"):
                max_allowed = s_limit -1
            if high > max_allowed:
                high = max_allowed
            if high >= low:
                num = high - low +1
                rem = p - i -1
                comp = variant.get("comp","pow_limit1_rem")
                if comp == "pow_limit1_rem":
                    completions = pow(s_limit+1, rem) if rem>=0 else 1
                elif comp == "pow_limit1_rem_plus1":
                    completions = pow(s_limit+1, rem+1)
                elif comp == "pow_limit_rem":
                    completions = pow(s_limit, rem) if rem>0 else 1
                elif comp == "pow_limit1_rem_minus":
                    completions = pow(s_limit+1, rem) - (1 if rem>=0 else 0)
                else:
                    completions = pow(s_limit+1, rem)
                count_less += num * completions
            # check tight continuation
            # bound allowed?
            if i==0 and bound==0:
                # if low==0 then 0 is allowed, else not
                if low==0:
                    if bound > max_allowed:
                        still_tight = False
                        break
                    else:
                        continue
                else:
                    still_tight=False
                    break
            if bound > max_allowed:
                still_tight=False
                break
        total += count_less
        if still_tight:
            # suffix compare
            suffix = xs[p:]
            op2 = variant.get("suffix_op","le")
            if op2 == "le":
                if s_str <= suffix:
                    total += 1
            elif op2 == "lt":
                if s_str < suffix:
                    total += 1
            elif op2 == "ge":
                if s_str >= suffix:
                    total += 1
            elif op2 == "gt":
                if s_str > suffix:
                    total += 1
            elif op2 == "always":
                total += 1
            elif op2 == "never":
                pass
        return total
    elif method == "convert":
        # convert prefix string to count of valid prefixes <= prefix
        # common leetcode trick: convert prefix digits clamp > limit to limit, then interpret as base limit+1
        pref_str = xs[:p]
        # clamping
        clamp = variant.get("clamp","cap")
        # cap means if digit > limit set to limit, and truncate rest? Actually proper method: find first digit > limit, set it to limit+? Hmm.
        # We'll implement several clamp variants
        # Simple: map each digit > limit to limit
        # Then interpret as base limit+1 number
        # Count = int(pref_base) + offset
        # offset handling for leading zero?
        # We'll brute several
        digits = list(map(int, pref_str))
        # clamp
        if clamp == "cap_each":
            # each digit > limit => limit
            clamped = [d if d <= s_limit else s_limit for d in digits]
        elif clamp == "cap_first_and_fill":
            # find first digit > limit, set it to limit, and all following to limit
            clamped = digits[:]
            for idx, d in enumerate(digits):
                if d > s_limit:
                    clamped[idx] = s_limit
                    for j in range(idx+1, len(clamped)):
                        clamped[j] = s_limit
                    break
        elif clamp == "cap_first_and_zero":
            clamped = digits[:]
            for idx, d in enumerate(digits):
                if d > s_limit:
                    clamped[idx] = s_limit
                    for j in range(idx+1, len(clamped)):
                        clamped[j] = 0
                    break
        elif clamp == "none":
            clamped = digits

        # convert clamped base limit+1 to integer
        base = s_limit + 1
        # value = sum digit * base^{pos}
        val = 0
