def count_range(X1,X2,limit,s,variant):
    # range [X1,X2]
    # variant controls offset
    offset = variant.get("range_offset","minus1") # minus1 means X1-1, minus0 means X1, etc.
    if offset == "minus1":
        return brute(limit,s,X2,variant) - brute(limit,s,X1-1,variant)
    elif offset == "start":
        return brute(limit,s,X2,variant) - brute(limit,s,X1,variant) + (1 if is_powerful(X1,limit,s) else 0)
    elif offset == "plus1":
        return brute(limit,s,X2,variant) - brute(limit,s,X1-1,variant) + variant.get("extra",0)
    else:
        return brute(limit,s,X2,variant) - brute(limit,s,X1-1,variant)

def is_powerful(x,limit,s):
    if not str(x).endswith(s):
        return False
    if any(int(c)>limit for c in str(x)):
        return False
    return True

